#include <iostream>
#include <vector>
using namespace std;
const long long INF = 1e18;
int main() {
    int n,e; cin >> n >> e;
    vector<vector<long long>> dist(n, vector<long long>(n, INF));
    for(int i=0; i<n; i++) dist[i][i]=0;
    for(int i=0; i<e; i++) { int u,v; long long w; cin>>u>>v>>w; dist[u][v]=min(dist[u][v],w); }
    // Floyd-Warshall
    return 0;
}

